const sketch = (p5obj:any) => {
p5obj.setup = () => 
{
  p5obj.createCanvas(1000,1000);
  p5obj.colorMode(p5obj.RGB,255);
  p5obj.background(55,155,0);
  //背景のグラデーション
  for(let g: number = 0; g<=1000; g++)
  {
    p5obj.noFill();
    p5obj.stroke(255-g*0.2,255-g*0.1,0);//線の色:黄色～緑
    p5obj.circle(500,500,g);
  }
  
  Okura(p5obj.random(360),200,500,500);
}

//オクラの断面の描画
const Okura = (Oangle: number, Olength: number, OcoreX: number, OcoreY: number) => {
  //スジの座標
  let OaX: number = Olength*p5obj.cos(p5obj.radians(Oangle))+OcoreX;
  let OaY: number = Olength*p5obj.sin(p5obj.radians(Oangle))+OcoreY;
  let ObX: number = Olength*p5obj.cos(p5obj.radians(Oangle+72))+OcoreX;
  let ObY: number = Olength*p5obj.sin(p5obj.radians(Oangle+72))+OcoreY;
  let OcX: number = Olength*p5obj.cos(p5obj.radians(Oangle+144))+OcoreX;
  let OcY: number = Olength*p5obj.sin(p5obj.radians(Oangle+144))+OcoreY;
  let OdX: number = Olength*p5obj.cos(p5obj.radians(Oangle+216))+OcoreX;
  let OdY: number = Olength*p5obj.sin(p5obj.radians(Oangle+216))+OcoreY;
  let OeX: number = Olength*p5obj.cos(p5obj.radians(Oangle+288))+OcoreX;
  let OeY: number = Olength*p5obj.sin(p5obj.radians(Oangle+288))+OcoreY;
  
  //分かれるスジの角度
  let Sangle: number = 5; //このパラメーターを変えることで模様を変化させる
  
  //中心のスジの描画
  p5obj.stroke(40,120,0);//スジの色
  p5obj.strokeWeight(1.5);//スジの太さ
  p5obj.line(OcoreX,OcoreY,OaX,OaY);
  p5obj.line(OcoreX,OcoreY,ObX,ObY);
  p5obj.line(OcoreX,OcoreY,OcX,OcY);
  p5obj.line(OcoreX,OcoreY,OdX,OdY);
  p5obj.line(OcoreX,OcoreY,OeX,OeY);
  
  //中心から分かれていくスジの描画
  if(Olength>30)//スジの長さが30以下なら再帰終了
  {
    Okura(Oangle+Sangle,Olength*0.5,OaX,OaY);
    Okura(Oangle-Sangle,Olength*0.5,OaX,OaY);
    Okura(Oangle+Sangle,Olength*0.5,ObX,ObY);
    Okura(Oangle-Sangle,Olength*0.5,ObX,ObY);
    Okura(Oangle+Sangle,Olength*0.5,OcX,OcY);
    Okura(Oangle-Sangle,Olength*0.5,OcX,OcY);
    Okura(Oangle+Sangle,Olength*0.5,OdX,OdY);
    Okura(Oangle-Sangle,Olength*0.5,OdX,OdY);
    Okura(Oangle+Sangle,Olength*0.5,OeX,OeY);
    Okura(Oangle-Sangle,Olength*0.5,OeX,OeY);
  }
  //輪郭を強調するスジの描画
  p5obj.line(OaX,OaY,ObX,ObY);
  p5obj.line(ObX,ObY,OcX,OcY);
  p5obj.line(OcX,OcY,OdX,OdY);
  p5obj.line(OdX,OdY,OeX,OeY);
  p5obj.line(OeX,OeY,OaX,OaY);
}

};

export default sketch;
