const sketch = (p5obj:any) => {
    p5obj.setup = () => {
//繧ｦ繧｣繝ｳ繝峨え縺ｮ蟷・→鬮倥＆繧・00 x 500縺ｫ險ｭ螳・
p5obj.createCanvas( 500, 500 );

//繝舌ャ繧ｯ繧ｰ繝ｩ繧ｦ繝ｳ繝芽牡繧堤區縺ｫ險ｭ螳・
p5obj.background( 0 );
//繧ｫ繝ｩ繝ｼ繝繝ｼ繝峨ｒHBS縺ｫ險ｭ螳・
p5obj.colorMode(p5obj.HSB, 300 );
//繝悶Ξ繝ｳ繝峨Β繝ｼ繝峨ｒ險ｭ螳・
p5obj.blendMode( p5obj.DIFFERENCE );
//霈ｪ驛ｭ邱壹ｒ蠑輔°縺ｪ縺・
p5obj.noStroke();
//荳ｭ蠢・・蠎ｧ讓吶→遏ｩ蠖｢縺ｮ蟷・→鬮倥＆繧呈欠螳・
p5obj.rectMode( p5obj.CENTER );

//邵ｦ縺ｮ髢馴囈繧・3縺ｫ險ｭ螳・
for ( var iY = 25; iY < 500; iY += 63 )
{
  //讓ｪ縺ｮ髢馴囈繧・3縺ｫ險ｭ螳・
  for ( var iX = 25; iX < 500; iX += 63 )
  {
    for ( var iDeg = 0; iDeg < 360; iDeg += 63 )
    {
      p5obj.push();
      p5obj.translate( iX, iY );

      //荳ｭ蠢・Κ縺ｮ蜀・・螟ｧ縺阪＆繧偵Λ繝ｳ繝繝縺ｫ險ｭ螳・
      p5obj.circle( 0, 0, p5obj.random( 0, 10 ) );
      //螟夜Κ縺ｮ蜀・・螟ｧ縺阪＆繧偵Λ繝ｳ繝繝縺ｫ險ｭ螳・
      p5obj.circle( 0, 0, p5obj.random( 30, 100 ) );


      p5obj.push();
    }
  }
}

  };
};

export default sketch;
