const sketch = (p5obj:any) => {
let preSec: number = 0;//前の秒　分　時を保存する
let preMinute: number = 0;
let preHour: number = 0;
let a: number = 0 ;
let b: number = 1;
let c: number = 1;
p5obj.setup = () => 
{
  p5obj.createCanvas(500, 500);

  p5obj.frameRate(60);
}

p5obj.draw = () => 
{
  p5obj.noStroke();
  p5obj.background(255, 0, 250);
  let s: number = p5obj.second();
  let m: number = p5obj.minute();
  let h: number = p5obj.hour();

  if (s != preSec)
  {
    a=0;
  }
  p5obj.fill(p5obj.random(150, 50), 200, p5obj.random(100, 350));
  p5obj.rect( 350, 500, 50, -(s*p5obj.height/59) );//過ぎた秒の概念の積み重ね
  p5obj.fill(250, 0, 100);
  p5obj.rect( 250, 500, 50, -(m*p5obj.height/59) );//過ぎた分の概念の積み重ね
  p5obj.fill(300, 100, 0);
  p5obj.rect( 150, 500, 50, -(h*p5obj.height/23) );//過ぎた時の概念の積み重ね

  p5obj.fill(p5obj.random(150, 50), 200, p5obj.random(100, 350));
  p5obj.rect(350, a*p5obj.height/59-(s*p5obj.height/59), 50, p5obj.height/59);
  preSec= s;//秒の概念の積み重ねる動作
  a++;

  if (m != preMinute)
  {
    b=0;
  }
  p5obj.fill(250, 0, 100);
  p5obj.rect(250, b*p5obj.height/59-(m*p5obj.height/59), 50, p5obj.height/59);
  preMinute = m;
  b++;//分の概念の積み重ねる動作

  if (h != preHour)
  {
    c=0;
  }
  p5obj.fill(300, 100, 0);
  p5obj.rect(150, c*p5obj.height/23-(h*p5obj.height/23), 50, p5obj.height/23);
  preHour= h;
  c++;//時の概念の積み重ねる動作
}

};

export default sketch;
