const sketch = (p:any) => {
    p.setup = () => {
p.createCanvas(500, 500);
p.colorMode(p.RGB, 1.0);
var fR, fG, fB;
for (var iX=0; iX<p.width; iX++)
{
  for (var iY=0; iY<p.height; iY++)
  {
    fR = p.sin(p.random(200))-p.cos(iY/50.0);
    fG = p.tan(iX*iY);
    fB = p.cos(p.pow(iX+200, 2)+p.pow(iY-1, 1));

    // draw pixel
    p.stroke(fR, fG, fB);
    p.point(iX, iY);
  }
}

  };
};

export default sketch;
