const sketch = (p5obj:any) => {
    p5obj.setup = () => {
p5obj.createCanvas(500, 500);
p5obj.background(255);
p5obj.noStroke();
for (var i= 0; i <= p5obj.width; i+=25)
{
  for (var j = 0; j <= p5obj.height; j+=25)
  {
    p5obj.fill(255, 255-i, 255-j, 150);
    p5obj.ellipse(j, i, 25 -j/10, 25 -j/10);
  }
}
for (var i= 0; i <= p5obj.width; i+=25)
{
  for (var j = 0; j <= p5obj.height; j+=25)
  {
    p5obj.fill(255-i, 255-j, 255, 150);
    p5obj.ellipse(i, j, 25 -j/10, 25 -j/10);
  }
}

  };
};

export default sketch;
