const sketch = (p5obj:any) => {
    p5obj.setup = () => {
p5obj.createCanvas(500, 500);
p5obj.colorMode(p5obj.RGB, 500, 500, 500);//繧ｫ繝ｩ繝ｼ繝｢繝ｼ繝会ｼ・GB縲・00谿ｵ髫趣ｼ・
p5obj.background(500, 500, 500);//閭梧勹逋ｽ
p5obj.noFill();//蝪励ｊ縺､縺ｶ縺励↑縺・
p5obj.strokeWeight(0.5);//邱壹・螟ｪ縺輔ｒ險ｭ螳・
for (var i=0; i<220; i=i+2)
{//110蝗樒ｹｰ繧願ｿ斐＠
  p5obj.stroke(500, 400, 0, 100);//邱壹・濶ｲ繧偵ｄ繧・乗・縺ｮ鮟・牡縺ｫ險ｭ螳・
  p5obj.ellipse(250, 300+i, i+35, i+35);
  //郢ｰ繧願ｿ斐＠縺斐→縺ｫ螟ｧ縺阪＆縲∽ｽ咲ｽｮ縺悟､峨ｏ繧九ｈ縺・↓蜀・ｒ謠上￥
  p5obj.ellipse(250, 200-i, i+35, i+35);
  p5obj.ellipse(300+i, 250, i+35, i+35);
  p5obj.ellipse(200-i, 250, i+35, i+35);
  p5obj.ellipse(200+i, 200+i, i+35, i+35);
  //郢ｰ繧願ｿ斐＠縺斐→縺ｫ螟ｧ縺阪＆縲∽ｽ咲ｽｮ縺悟､峨ｏ繧九ｈ縺・↓蜀・ｒ謠上￥
  p5obj.ellipse(200+i, 300-i, i+35, i+35);
  p5obj.ellipse(300-i, 200+i, i+35, i+35);
  p5obj.ellipse(300-i, 300-i, i+35, i+35);
  p5obj.stroke(500, 2*i, 500-2*i, 100);
  //邱壹・濶ｲ繧貞､門・縺ｫ縺・￥縺ｻ縺ｩ繝斐Φ繧ｯ縺九ｉ繧ｪ繝ｬ繝ｳ繧ｸ縺ｫ螟峨ｏ繧九ｈ縺・↓險ｭ螳・
  p5obj.ellipse(250, 250+i, i+70, i+70);
  //郢ｰ繧願ｿ斐＠縺斐→縺ｫ螟ｧ縺阪＆縲∽ｽ咲ｽｮ縺悟､峨ｏ繧九ｈ縺・↓蜀・ｒ謠上￥
  p5obj.ellipse(250, 250-i, i+70, i+70);
  p5obj.ellipse(250+i, 250, i+70, i+70);
  p5obj.ellipse(250-i, 250, i+70, i+70);
  p5obj.ellipse(250+0.7*i, 250+0.7*i, i+70, i+70);
  //郢ｰ繧願ｿ斐＠縺斐→縺ｫ螟ｧ縺阪＆縲∽ｽ咲ｽｮ縺悟､峨ｏ繧九ｈ縺・↓蜀・ｒ謠上￥
  p5obj.ellipse(250+0.7*i, 250-0.7*i, i+70, i+70);
  p5obj.ellipse(250-0.7*i, 250+0.7*i, i+70, i+70);
  p5obj.ellipse(250-0.7*i, 250-0.7*i, i+70, i+70);
}

  };
};

export default sketch;
