const sketch = (p5obj:any) => {
/**
 關ｽ縺｡繧区ｰｴ貊ｴ縺ｨ轤ｹ貊・☆繧句・縺ｧ遘偵ｒ縲∽ｸ｡讓ｪ縺ｧ邱壹→邱壹ｒ莠､蟾ｮ縺輔○縺淌怜魂縺ｮ菴咲ｽｮ縺ｧ譎る俣繧定｡ｨ迴ｾ縲・
 縺ｲ縺怜ｽ｢縺梧ｺ懊∪繧翫″縺｣縺溘ｉ・大・縺溘▲縺溘％縺ｨ縺ｫ縺ｪ繧九・
 逵溘ｓ荳ｭ縺ｮ豌ｴ貊ｴ縺梧ｺ懊∪縺｣縺ｦ縺・￥縺ｲ縺怜ｽ｢縺ｨ縲√◎縺ｮ蜻ｨ繧翫・蝗ｳ蠖｢縺ｧ髫咎俣繧剃ｽ懊ｊ縲・
 蠕後ｍ縺九ｉ繧ｰ繝ｩ繝・・繧ｷ繝ｧ繝ｳ縺ｫ縺ｪ縺｣縺ｦ縺・ｋ蝗ｳ蠖｢繧偵・縺槭°縺帙ｋ縺薙→縺ｧ蛻・焚繧定｡ｨ縺励◆縲・
 轤ｹ貊・☆繧玖ｵ､荳ｸ縺ｯ縲∫ｧ偵→蛻・ｒ6蛻・牡縺励∵凾髢薙〒縺ｯ逶ｮ逶帙ｊ縺後後％縺薙°繧峨％縺薙∪縺ｧ蜍輔￥縲阪％縺ｨ繧堤､ｺ縺吶・
 */

let Y: number = 0.0;
let speed: number = 0.0;
let kasokudo: number = 0.3;//蜉騾溷ｺｦ
let count: number = 0;
let iSecondCurrent: number;
let X: number;

p5obj.setup = () => 
{
  p5obj.createCanvas(1000, 700);
  p5obj.colorMode(p5obj.RGB, 255, 255, 255, 1);
  p5obj.frameRate(60);
  iSecondCurrent = p5obj.second();
  X = 0;
}

p5obj.draw = () => 
{
  p5obj.noStroke();
  p5obj.rectMode(p5obj.CORNER);
  let s: number = p5obj.second();
  let m: number = p5obj.minute();
  let h: number = p5obj.hour();
  console.log(h+":"+m+":"+s);//譎ょ綾遒ｺ隱咲畑
  p5obj.background(45, 75, 75);

  //蛻・・謠冗判
  for (let mi: number = 0; mi<50; mi+=10)//蛻・・陦ｨ遉ｺ縺ｮ蝗ｳ蠖｢
  {
    p5obj.fill(70-mi, 230-mi, 205-mi, 1-mi*(0.02));//繧ｰ繝ｩ繝・・繧ｷ繝ｧ繝ｳ
    p5obj.rect(200, 40-mi+10*m, 600, 10);
  }
  if (m<5)//蛻・・蝗ｳ蠖｢縺ｮ菴咎渊
  {
    for (let mi: number = 0; mi<50; mi+=10)
    {
      p5obj.fill(70-mi, 230-mi, 205-mi, 1-mi*(0.02));
      p5obj.rect(200, 640-mi+10*m, 600, 10);
    }
  }//縺薙％縺ｾ縺ｧ菴咎渊
  p5obj.fill(30, 60, 60);//蜻ｨ繧翫ｒ蜿ｰ蠖｢縺ｨ髟ｷ譁ｹ蠖｢縺ｧ蝗ｲ縺・
  let z: number = p5obj.sqrt(50);
  p5obj.rect(350, 650, 300, 60);
  p5obj.rect(350, 0, 300, 50);
  p5obj.quad(505, 150-z, 1000, 645-z, 1000, 0, 505, 0);
  p5obj.quad(505, 550+z, 1000, 55+z, 1000, 700, 505, 700);
  p5obj.quad(495, 150-z, 495, 0, 0, 0, 0, 645-z);
  p5obj.quad(495, 550+z, 0, 55+z, 0, 700, 495, 700); //縺薙％縺ｾ縺ｧ蜻ｨ繧雁峇縺・

  //遘偵・謠冗判
  count++;
  p5obj.fill(30, 60, 60);//豼・＞髱堤ｷ第棧
  p5obj.quad(500, 150, 700, 350, 500, 550, 300, 350);
  p5obj.fill(45, 75, 75);//豼・＞髱堤ｷ代ｈ繧雁ｰ代＠阮・＞譁ｹ縺ｮ譫
  p5obj.quad(500, 165, 685, 350, 500, 535, 315, 350);
  p5obj.fill(225, 40, 40);//襍､譫
  p5obj.quad(500, 260, 590, 350, 500, 440, 410, 350);
  p5obj.fill(45, 75, 75);
  p5obj.quad(500, 267, 583, 350, 500, 433, 417, 350);//縺薙％縺ｾ縺ｧ譫
  //豌ｴ貊ｴ繧定誠縺ｨ縺・
  speed+=kasokudo;
  Y+=speed;
  p5obj.fill(70, 230, 205, 1);
  p5obj.ellipse(500, 165+Y, 12, 12);
  let iSecondNew: number = p5obj.second();
  if ( iSecondCurrent != iSecondNew )//1遘偵↓1邊定誠縺｡繧・
  {
    iSecondCurrent = iSecondNew;
    Y=0;
    count=0;
  }
  if (207+Y>=550)//豌ｴ貊ｴ縺瑚誠縺｡蟋九ａ繧句ｺｧ讓・
  {
    speed=0;
  }//1遘堤ｵ後▽縺ｾ縺ｧ豌ｴ貊ｴ繧呈ｭ｢繧√ｋ縲√％縺薙∪縺ｧ豌ｴ貊ｴ
  if (s<=30)//縺ｿ縺壹◆縺ｾ繧翫・謠冗判
  {
    p5obj.triangle(500, 530, 500-s*(180/30), 530-s*(180/30), 500+s*(180/30), 530-s*(180/30));
  }
  if (s>=30)//
  {
    p5obj.beginShape();
    p5obj.vertex(500, 530);
    p5obj.vertex(320, 350);
    p5obj.vertex(320+(s-30)*(180/30), 350-(s-30)*(180/30));
    p5obj.vertex(680-(s-30)*(180/30), 350-(s-30)*(180/30));
    p5obj.vertex(680, 350);
    p5obj.endShape(p5obj.CLOSE);
  }//縺薙％縺ｾ縺ｧ縺ｿ縺壹◆縺ｾ繧・

  //譎る俣謠冗判,譎りｨ亥屓繧・
  p5obj.strokeWeight(2);//邱・
  p5obj.stroke(70, 230, 205, 1);
  p5obj.line(660, 230, 780, 350);
  p5obj.line(660, 470, 780, 350);
  p5obj.line(340, 230, 220, 350);
  p5obj.line(340, 470, 220, 350);
  if (0<=h&&h<=5)//蜿ｳ荳・譎ゅ°繧・譎・
  {
    p5obj.line(660+h*80/5, 270+h*80/5, 700+h*80/5, 230+h*80/5);
    p5obj.rectMode(p5obj.CENTER);
    p5obj.rect( 680+h*80/5, 250+h*80/5, 10, 10);
  }
  if (5<h&&h<=11)//蜿ｳ荳・譎ゅ°繧・1譎・
  {
    p5obj.line(740-(h-6)*80/5, 350+(h-6)*80/5, 780-(h-6)*80/5, 390+(h-6)*80/5);
    p5obj.rectMode(p5obj.CENTER);
    p5obj.rect( 760-(h-6)*80/5, 370+(h-6)*80/5, 10, 10);
  }
  if (11<h&&h<=17)//蟾ｦ荳・2譎ゅ°繧・7譎・
  {
    p5obj.line(340-(h-12)*80/5, 430-(h-12)*80/5, 300-(h-12)*80/5, 470-(h-12)*80/5);
    p5obj.rectMode(p5obj.CENTER);
    p5obj.rect( 320-(h-12)*80/5, 450-(h-12)*80/5, 10, 10);
  }
  if (17<h&&h<=23)//蟾ｦ荳・8譎ゅ°繧・3譎・
  {
    p5obj.line(260+(h-18)*80/5, 350-(h-18)*80/5, 220+(h-18)*80/5, 310-(h-18)*80/5);
    p5obj.rectMode(p5obj.CENTER);
    p5obj.rect( 240+(h-18)*80/5, 330-(h-18)*80/5, 10, 10);
  }

  //逶ｮ逶帙ｊ
  p5obj.strokeWeight(6);//豌ｴ縺梧ｺ縺｡縺溷ｾ瑚ｦ九∴繧矩上￠縺溯ｵ､蝗幄ｧ・
  p5obj.stroke(225, 40, 40, 0.3);
  p5obj.noFill();
  p5obj.quad(500, 263, 587, 350, 500, 436, 413, 350);
  p5obj.noStroke();
  p5obj.fill(255-1.5*count, 70-1.5*count, 70-1.5*count);//轤ｹ貊・☆繧玖ｵ､荳ｸ驕・
  p5obj.circle(500, 150, 6);
  p5obj.circle(600, 250, 6);
  p5obj.circle(700, 350, 6);
  p5obj.circle(600, 450, 6);
  p5obj.circle(500, 550, 6);
  p5obj.circle(700, 230, 4);
  p5obj.circle(780, 310, 4);
  p5obj.circle(780, 390, 4);
  p5obj.circle(700, 470, 4);
  p5obj.circle(300, 470, 4);
  p5obj.circle(220, 390, 4);
  p5obj.circle(220, 310, 4);
  p5obj.circle(300, 230, 4);
}

};

export default sketch;
