const sketch = (p5obj:any) => {
/**
 
 繝ｩ繝ｳ繝繝縺ｪ轤ｹ謠上↓繧医ｋ繝・ず繧ｿ繝ｫ譎りｨ・
 蛻・ｄ譎ゅ′蛻・ｊ譖ｿ繧上▲縺溷ｾ鯉ｼ悟ｾ舌・↓謠冗判縺悟､牙喧縺励※縺・￥・・
 
 */

// 譎る俣陦ｨ遉ｺ縺ｮ繧ｹ繧ｱ繝ｼ繝ｫ蛟､[・医せ繧ｯ繝ｪ繝ｼ繝ｳ縺ｮ・牙ｹ・↓蟇ｾ縺吶ｋ邇・鬮倥＆縺ｫ蟇ｾ縺吶ｋ邇Ⅹ
const DIGITS_SCALE: number[] = [  0.80, 0.60  ];

// 蜷・｡・俣縺ｮ髢馴囈 荳譯∝・縺ｮ蟷・↓蟇ｾ縺吶ｋ邇・
const DIGIT_INTERVAL: number = 0.6;
// 繧ｳ繝ｭ繝ｳ縺ｮ蟷・荳譯∝・縺ｮ蟷・↓蟇ｾ縺吶ｋ邇・
const COLON_WIDTH_RATE: number = 0.1;

// 譯∫分蜿ｷ 01:23
// 蜷・｡√・蠎ｧ讓兌譯∫分蜿ｷ][x,y]
let fDigitPos: number[][] = new Array(4).fill([]).map(() => new Array(2));

// 蜷・｡√・繧ｵ繧､繧ｺ[譯∫分蜿ｷ][w,h]
let fDigitSize: number[][] = new Array(4).fill([]).map(() => new Array(2));

// 繧ｳ繝ｭ繝ｳ縺ｮ謖ｿ蜈･蝣ｴ謇(譯∫分蜿ｷ縺ｫ蟇ｾ蠢・
const COLON_LOC_IDX: number = 2;

/** 繧ｻ繧ｰ繝｡繝ｳ繝育分蜿ｷ
 4
 -
 0|5|2
 -
 1| |3
 -
 6
 */
// 繧ｻ繧ｰ繝｡繝ｳ繝育ｯ・峇縺ｮ蟾ｦ荳雁ｺｧ讓・[繧ｻ繧ｰ繝｡繝ｳ繝育分蜿ｷ][x,y]
let fSegmentUpperLeft: number[][] = new Array(7).fill([]).map(() => new Array(2));
// 繧ｻ繧ｰ繝｡繝ｳ繝育ｯ・峇縺ｮ繧ｵ繧､繧ｺ [繧ｻ繧ｰ繝｡繝ｳ繝育分蜿ｷ][w,h]
let fSegmentSize: number[][] = new Array(7).fill([]).map(() => new Array(2));
// 繧ｻ繧ｰ繝｡繝ｳ繝亥酔螢ｫ縺ｮ驥阪↑繧・[0-1]
let fSegmentsLap: number = 0.5;
// 繧ｻ繧ｰ繝｡繝ｳ繝医・螟ｪ縺・[0-1]
let fSegmentsThickness: number[] = [  0.2, 0.1  ];

// 謨ｰ縺ｫ蟇ｾ縺励※・瑚｡ｨ遉ｺ繧定｡後≧縺九・繝輔Λ繧ｰ[讓咏､ｺ謨ｰ蛟､] [繧ｻ繧ｰ繝｡繝ｳ繝育分蜿ｷ]
const DIGIT_DISP_FLG: boolean[][] = [[ true, true, true, true, true, false, true], //0
  [false, false, true, true, false, false, false], //1
  [false, true, true, false, true, true, true], //2
  [false, false, true, true, true, true, true], //3
  [true, false, true, true, false, true, false], //4
  [true, false, false, true, true, true, true], //5
  [true, true, false, true, true, true, true], //6
  [true, false, true, true, true, false, false], //7
  [true, true, true, true, true, true, true], //8
  [true, false, true, true, true, true, false ]];//9


p5obj.setup = () => 
{
  // 繧ｹ繧ｯ繝ｪ繝ｼ繝ｳ繧ｵ繧､繧ｺ(窶ｻ謇句・蜉・
  p5obj.createCanvas( 800, 450 );

  let iDigitsCount: number = fDigitPos.length;  // 譯√・謨ｰ

  // 蜷・｡√・蠎ｧ讓吶→蟷・
  let fDigitsWidth: number = p5obj.width * DIGITS_SCALE[0];
  let fDigitWidth: number = fDigitsWidth / (iDigitsCount*(1+DIGIT_INTERVAL)+COLON_WIDTH_RATE);
  let fDigitHeight: number = p5obj.height * DIGITS_SCALE[1];
  let fDigitInterval: number = fDigitWidth * DIGIT_INTERVAL;
  let fDigitPosX: number = ( p5obj.width - fDigitsWidth ) / 2.0;
  for (let iDigitIdx: number = 0; iDigitIdx < fDigitPos.length; iDigitIdx++)
  {
    // 繧ｳ繝ｭ繝ｳ縺ｮ蝣ｴ謇繧呈諺蜈･.
    if ( iDigitIdx == COLON_LOC_IDX)
    {
      fDigitPosX += fDigitWidth*COLON_WIDTH_RATE + fDigitInterval;
    }
    fDigitPos[iDigitIdx][0] = fDigitPosX;
    fDigitPos[iDigitIdx][1] = ( p5obj.height - fDigitHeight ) / 2.0;
    fDigitSize[iDigitIdx][0] = fDigitWidth;
    fDigitSize[iDigitIdx][1] = fDigitHeight;
    fDigitPosX += fDigitWidth + fDigitInterval;
  }

  // 邵ｦ髟ｷ縺ｨ讓ｪ髟ｷ縺ｮ繧ｻ繧ｰ繝｡繝ｳ繝医・繧ｵ繧､繧ｺ[w,h]
  let fSegmentSizeV: number[] = new Array(2).fill([]);
  let fSegmentSizeH: number[] = new Array(2).fill([]);
  fSegmentSizeV[0] = fSegmentsThickness[0] * fDigitWidth;
  fSegmentSizeH[1] = fSegmentsThickness[1] * fDigitHeight;
  fSegmentSizeV[1] = ( fDigitHeight - (1-fSegmentsLap)*(3 * fSegmentSizeH[1]) ) / 2.0;
  fSegmentSizeH[0] = fDigitWidth - (1-fSegmentsLap)* (2 * fSegmentSizeV[0]);

  // 蜷・そ繧ｰ繝｡繝ｳ繝医・繝ｭ繝ｼ繧ｫ繝ｫ蠎ｧ讓・
  let fSegmentOfs: number[] = [  ( fDigitWidth - fSegmentSizeH[0] )    / 2.0,
    ( fDigitHeight - 2*fSegmentSizeV[1] ) / 3.0  ];
  fSegmentUpperLeft[0][0] = 0.0;
  fSegmentUpperLeft[1][0] = 0.0;
  fSegmentUpperLeft[2][0] = fDigitWidth - fSegmentSizeV[0];
  fSegmentUpperLeft[3][0] = fSegmentUpperLeft[2][0];
  fSegmentUpperLeft[4][0] = fSegmentOfs[0];
  fSegmentUpperLeft[5][0] = fSegmentOfs[0];
  fSegmentUpperLeft[6][0] = fSegmentOfs[0];
  fSegmentUpperLeft[4][1] = 0;
  fSegmentUpperLeft[0][1] = fSegmentOfs[1];
  fSegmentUpperLeft[2][1] = fSegmentOfs[1];
  fSegmentUpperLeft[5][1] = fDigitHeight / 2.0 - fSegmentSizeH[1] / 2.0;
  {
    let fOfsY: number = fSegmentSizeV[1] + 2 * fSegmentOfs[1];
    fSegmentUpperLeft[1][1] = fOfsY;
    fSegmentUpperLeft[3][1] = fOfsY;
  }
  fSegmentUpperLeft[6][1] = fDigitHeight - fSegmentSizeH[1];
  for (let iSegmentIdx: number = 0; iSegmentIdx <= 3; iSegmentIdx++)
  {
    fSegmentSize[iSegmentIdx][0] = fSegmentSizeV[0];
    fSegmentSize[iSegmentIdx][1] = fSegmentSizeV[1];
  }
  for (let iSegmentIdx: number = 4; iSegmentIdx < fSegmentUpperLeft.length; iSegmentIdx++)
  {
    fSegmentSize[iSegmentIdx][0] = fSegmentSizeH[0];
    fSegmentSize[iSegmentIdx][1] = fSegmentSizeH[1];
  }

  p5obj.background(50, 50, 50);
  p5obj.colorMode(p5obj.RGB, 256);
  p5obj.frameRate(12);
}

p5obj.draw = () => 
{
  // 轤ｹ謠上Ξ繝ｳ繝繝ｪ繝ｳ繧ｰ
  let iHour: number = p5obj.hour() ;
  let iMinute: number = p5obj.minute();
  let iDispNumbers: number[] = [  Math.floor(iHour/10), Math.floor(iHour%10), Math.floor(iMinute/10), Math.floor(iMinute%10)  ];
  p5obj.noStroke();
  for (let iDigitIdx: number = 0; iDigitIdx < fDigitPos.length; iDigitIdx++)
  {
    let iDispNumber: number = iDispNumbers[iDigitIdx];
    for (let iSegmentIdx: number = 0; iSegmentIdx < fSegmentUpperLeft.length; iSegmentIdx++)
    {
      console.log(`iDispNumber: ${iDispNumber}`);
      if ( DIGIT_DISP_FLG[iDispNumber][iSegmentIdx] )
      {
        p5obj.fill(p5obj.random(255), p5obj.random(255), p5obj.random(255), 50);  // 轤ｹ謠・
      } else
      {
        p5obj.fill(50, 50, 50, 50);                          //縲蠕舌・↓繝輔ぉ繝ｼ繝峨い繧ｦ繝・
      }
      
      p5obj.circle( fSegmentUpperLeft[iSegmentIdx][0]+fDigitPos[iDigitIdx][0] + p5obj.random(fSegmentSize[iSegmentIdx][0]),
        fSegmentUpperLeft[iSegmentIdx][1]+fDigitPos[iDigitIdx][1] + p5obj.random(fSegmentSize[iSegmentIdx][1]),
        6+p5obj.random(10))  ;
    }
  }
}

};

export default sketch;
