const sketch = (p5obj:any) => {
p5obj.setup = () => 
{
  p5obj.createCanvas(1000, 1000);
  p5obj.colorMode(p5obj.RGB);
  p5obj.noLoop();
  p5obj.stroke(0);
  shikaku(0, 0, 1000,5);
  katachi(0,1000,5);
}
const shikaku = (a: number, b: number, m: number, x: number) => {
  p5obj.fill(p5obj.random(250),100,p5obj.random(150));
  p5obj.rect(a,b,m,m);
  katachi(a,b,m);
  let c: number = m/2;
  let d: number = p5obj.map(x, 0, 4, 0.45, 0);
  x--;
  if (x >= 0) {
    if (p5obj.random(1) > d) 
    {
      shikaku(a, b, c, x);
      shikaku(a+c, b, c, x);
      shikaku(a+c, b+c, c, x);
      shikaku(a, b+c, c, x);
    }
  }
}
 
const mousePressed = () => {
  p5obj.redraw();
}
 
const katachi = (A: number, B: number, C: number) => {
  let D: number = C/2;
  p5obj.push();
  p5obj.translate(A+D,B+D);
  p5obj.fill(p5obj.random(250),100,p5obj.random(150));
  if (p5obj.random(1) > 1.0/2.0)
  {
  p5obj.triangle(D, D,-D,-D, D,-D);
  }
  else if (p5obj.random(1) > 1.0/2.0)
  {
  p5obj.rect(D, -D, C,C);
  }
  else
  {
   p5obj.ellipse(D,-D, C, C);
  }
  p5obj.pop();
}
const keyPressed = () => {
  if(p5obj.keyCode  ==  p5obj.ENTER)
  {
  p5obj.save("a19_yoshida.png");
  }
}

};

export default sketch;
