const sketch = (p5obj:any) => {
    p5obj.setup = () => {
p5obj.createCanvas(500, 500);
p5obj.colorMode(p5obj.HSB, 500);
p5obj.background(300);
p5obj.strokeWeight(0.5);
p5obj.noFill();

for (var iX=0; iX<550; iX+=20)
{
  for (var iY=0; iY<550; iY+=50)
  {
    p5obj.stroke(iX, 500, 500);
    p5obj.ellipse(iX, iY, 400, 50);
  }
}

  };
};

export default sketch;
